<?php
require_once('includes/load.php');
error_reporting(E_ALL);
ini_set('display_errors', true);
date_default_timezone_set('Asia/Manila');
require_once 'dompdf/autoload.inc.php';
use Dompdf\Dompdf;
use Dompdf\Options;

$dompdf = new Dompdf();

$options = new Options();
$options->set('isHtml5ParserEnabled', true);
$options->set('isPhpEnabled', true);
$dompdf = new Dompdf($options);

$sales = daily_sales();
$user = current_user();
$html = '';
$html .= 'text-uppercase
    <!DOCTYPE html>
    <html lang="en">
    <head>
    <link rel="stylesheet" href="/bootstrap/bootstrap.css">
    <script src="/bootstrap/bootstrap.js"></script>
    </head>
        <style>
            th, td {
                padding: 10px;
                border: 1px solid black;
            }

            .text-uppercase{
                text-transform:uppercase
            }

            h5{
                font-size: 16px !important;
                text-align: center;
                letter-spacing:1px
            }
            .font-size {
                font-size: 14px !important;
                text-align: center;
            }

            body {
                font-family: Arial, sans-serif;
            }
            .header {
                text-align: center;
                margin-bottom: 20px;
            }

            .contact-info {
                font-size: 14px;
                margin-bottom: 10px;
                text-transform: uppercase;
            }

            .table{
                width: 100%;
                border-collapse: collapse;
                margin-bottom: 20px;
            }

            .table thead {
                font-size: 12px;
                font-weight: 500;
            }
            header{
                line-height:6px;
                text-align:center;
            }
            footer{
                text-align:center;
                line-height:5px;
                font-size:14px;
                text-transform:uppercase;
                margin-top:50px;
            }
            .label{
                color:#1e1e1e;
                font-size:11px;
            }
            .label2{
                color:#1e1e1e;
                margin-top:25px;
                font-size:11px;
            }
            img{
                margin-bottom:10px;
            }
        </style>
    <body>
        <header class="text-center lh-base">
            <img class="mb-2" src="data:image/jpeg;base64," style="width: 200px" alt="logo">
            <p">BUBBLE JAQ SHAKE AND TEAS</p>
            <p">46, Rizal Avenue Extension, Caloocan City, Metro Manila</p>
            <p>sales.bubblejaq@gmail.com</p>
            <p>09283521893</p>
        </header>
        <div class="section mt-4">
            <h5 class="fw-bold text-uppercase">SALES SUMMARY FOR '.date("F j, Y") .'</h5>
            <table id="table" class="table table-sm table-bordered text-center align-middle mt-3">  
                <thead>
                    <tr>
                        <th class="text-center">No.</th>
                        <th class="text-center">Product</th>
                        <th class="text-center">Size</th>
                        <th class="text-center">Quantity</th>
                        <th class="text-center">Price</th>
                        <th class="text-center">Sold by</th>
                        <th class="text-center">Total</th>
                        <th class="text-center">Time</th>
                    </tr>
                </thead>
                <tbody>
';
if (!$sales) {
    $html .= '
        <tr class="font-size font">
            <td colspan="8">NO SALES FOUND</td>
        </tr>
    ';
}else {
    $totalSales = 0;
    $counter = 1;
    foreach ($sales as $sale) {
        $totalSalePerRow = $sale["qty"] * $sale["price"];
        $totalSales += $totalSalePerRow; 
        $html .= '
            <tr class="font-size font">
                <td class="text-center">' . $counter . '</td>
                <td>' . $sale["name"] . ' </td>
                <td>' . $sale["item_size"] . '</td>
                <td class="col-1">' . (int)$sale["qty"] . ' </td>
                <td>' . $sale["price"] . ' </td>
                <td>' . $sale["employee"] . ' </td>
                <td>' . $totalSalePerRow.'.00 </td>
                <td>' . date("g:i A", strtotime($sale["created_date"])) . ' </td>
            </tr>
        ';
        $counter++;
    }
    $html .= '
    <tr class="font-size font">
        <td colspan="8" class="text-end"><strong>TOTAL SALES: '. number_format($totalSales, 2) . '</strong></td>
    </tr>
';
}

$html .= '
                </tbody>
            </table>
        </div>
        <footer>
            <p class="label"> Generated On </p>
            <p> ' . date("F j, Y | g:i A") . ' </p>
            <p class="label2">Generated By   </p>
            <p> ' . remove_junk(ucfirst($user['name'])) . '</p>
        </footer>
    </body>
    </html>
';

$dompdf->loadHtml($html);
$dompdf->setPaper('A4', 'portrait');
$dompdf->render();
$options = $dompdf->getOptions();
$options->set('isRemoteEnabled', true); 
$dompdf->setOptions($options);
$dompdf->stream('Sales Report For '.date("F j, Y").'.pdf', array('Attachment' => 0));
?>